describe('Virus Scan Status for Uploaded Files', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
    cy.get('[data-testid="file-upload-container"]').should('be.visible');
  });

  it('should display virus scan status as "scanning" immediately after file upload', () => {
    const fileName = 'test-document.pdf';

    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.pdf', { force: true });

    cy.get('[data-testid="file-item"]').should('exist');
    cy.get('[data-testid="scan-status"]').should('contain', 'Scanning...');
    cy.get('[data-testid="scan-status-icon"]').should('have.class', 'scanning');

    cy.get('[data-testid="file-name"]').should('contain', fileName);
  });

  it('should update virus scan status to "clean" after successful scan completion', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.pdf', { force: true });

    cy.get('[data-testid="scan-status"]').should('contain', 'Scanning...');

    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Clean');
    cy.get('[data-testid="scan-status-icon"]').should('have.class', 'clean');
    cy.get('[data-testid="scan-status-badge"]').should('have.css', 'background-color', 'rgb(34, 197, 94)');
  });

  it('should display virus scan status as "infected" when malware is detected', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/infected-file.exe', { force: true });

    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Infected');
    cy.get('[data-testid="scan-status-icon"]').should('have.class', 'infected');
    cy.get('[data-testid="scan-status-badge"]').should('have.css', 'background-color', 'rgb(239, 68, 68)');
    cy.get('[data-testid="file-action-download"]').should('be.disabled');
    cy.get('[data-testid="infection-warning"]').should('be.visible').and('contain', 'This file contains malware');
  });

  it('should display virus scan status as "failed" when scan encounters an error', () => {
    cy.intercept('POST', '/api/scan-file', { statusCode: 500, body: { error: 'Scan service unavailable' } });

    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.pdf', { force: true });

    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Scan Failed');
    cy.get('[data-testid="scan-status-icon"]').should('have.class', 'failed');
    cy.get('[data-testid="scan-error-message"]').should('be.visible').and('contain', 'Unable to scan file');
    cy.get('[data-testid="retry-scan-button"]').should('be.visible');
  });

  it('should display scan status for multiple uploaded files independently', () => {
    cy.get('[data-testid="file-input"]').selectFile(['cypress/fixtures/test-document.pdf', 'cypress/fixtures/image.jpg'], { force: true });

    cy.get('[data-testid="file-item"]').should('have.length', 2);

    cy.get('[data-testid="file-item"]').first().within(() => {
      cy.get('[data-testid="scan-status"]').should('contain', 'Scanning...');
    });

    cy.get('[data-testid="file-item"]').last().within(() => {
      cy.get('[data-testid="scan-status"]').should('contain', 'Scanning...');
    });

    cy.get('[data-testid="file-item"]').first().within(() => {
      cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Clean');
    });

    cy.get('[data-testid="file-item"]').last().within(() => {
      cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Clean');
    });
  });

  it('should allow retry of failed virus scan', () => {
    cy.intercept('POST', '/api/scan-file', { statusCode: 500 }).as('failedScan');

    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.pdf', { force: true });
    cy.wait('@failedScan');

    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Scan Failed');

    cy.intercept('POST', '/api/scan-file', { statusCode: 200, body: { status: 'clean' } }).as('successScan');

    cy.get('[data-testid="retry-scan-button"]').click();
    cy.wait('@successScan');

    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Clean');
    cy.get('[data-testid="retry-scan-button"]').should('not.exist');
  });

  it('should display scan timestamp for completed scans', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-document.pdf', { force: true });

    cy.get('[data-testid="scan-timestamp"]', { timeout: 10000 }).should('be.visible');
    cy.get('[data-testid="scan-timestamp"]').should('match', /\d{1,2}\/\d{1,2}\/\d{4}/);
  });

  it('should handle empty file upload gracefully', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/empty-file.txt', { force: true });

    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Clean');
    cy.get('[data-testid="file-size-warning"]').should('not.exist');
  });
});
